"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[6343],{67351:o=>{o.exports=JSON.parse('{"tag":{"label":"Workbooks","permalink":"/datagol-knowlegde-base-v1/docs/tags/workbooks","allTagsPath":"/datagol-knowlegde-base-v1/docs/tags","count":29,"items":[{"id":"Workbooks/Accessing workbook pipeline information","title":"Accessing workbook pipeline information","description":"1.  On the Home page, from the left navigation panel, click Workspace, and from the list of workspaces, open the workspace where the workbook that you want to edit is located.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/accessing-workbook-pipeline-information"},{"id":"Workspaces/Accessing workspaces","title":"Accessing workspaces","description":"To access a workspace, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/accessing-workspace"},{"id":"Workbooks/Copying cURL for workbook API interaction","title":"Copying cURL for workbook API interaction","description":"You can copy the cURL command to interact with the workbook using API requests. This command includes the necessary method, headers, and parameters for easy integration.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/copying-CURL-for-workbooks-API-Interaction"},{"id":"Workbooks/Creating workbook with file upload","title":"Creating workbook with file upload","description":"1.  On the Home page, from the left navigation panel, click Workspace, and from the list of workspaces, open a workspace.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/creating-workbook-with-file-upload"},{"id":"Workspaces/Creating workspace","title":"Creating workspace","description":"To create a workspace, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/create-workspace"},{"id":"Workbooks/Data grouping","title":"Data grouping","description":"Grouping workbook data against a chosen column offers a powerful way to reorganize and understand your information from different angles. Instead of just seeing a flat list of entries, you can create a hierarchical view where rows with the same value in your selected column are brought together. This aggregation allows you to analyze trends, summaries, and patterns specific to those groups.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/data-grouping"},{"id":"Workbooks/Deleting a workbook","title":"Deleting a workbook","description":"Ensure that the workbook is not delete-protected before deleting it. If it is, you must first remove the delete protection status. Refer to Disable delete protection for workbooks for instructions.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/deleting-a-workbook"},{"id":"Workbooks/Disable delete protection","title":"Disable delete protection","description":"To disable delete protection for workbooks, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/disable-delete-protection"},{"id":"Workbooks/Downloading data from workbooks","title":"Downloading data from workbooks","description":"There are two primary ways to download data from your workbooks, each with distinct behaviors:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/downloading-data-from-workbooks"},{"id":"Workbooks/Downloading raw CSV for workbooks","title":"Downloading raw CSV for workbooks","description":"To download raw CSV for workbooks, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/downloading-raw-csv-for-workbooks"},{"id":"Workbooks/Downloading raw Excel for workbooks","title":"Downloading raw Excel for workbooks","description":"To download raw Excel for workbook, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/downloading-raw-excel-for-workbooks"},{"id":"Workbooks/Configure workbook settings/Editing name and description of a workbook","title":"Editing name and description of a workbook","description":"To edit the name and description of a workbook, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/Configure workbook settings/editing-name-and-description-of-a-workbook"},{"id":"Workbooks/Email campaign","title":"Email campaign","description":"You can now create email campaigns from Workbooks by selecting a view (master or filtered) and a recipient column (email or user). The view filters the recipients, sending the email only to a subset of members in the email or user column, rather than all of them.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/email-campaign"},{"id":"Workbooks/Enabling delete protection","title":"Enabling delete protection","description":"Enabling delete protection is highly recommended if your workbook is used in embedded analytics or as an API by another service. This ensures that critical data and configurations remain intact and prevents accidental or unauthorized deletions.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/enable-disable-delete-protection"},{"id":"Workbooks/Extracting data from documents","title":"Extracting data from documents","description":"What is data extraction?","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/extracting-data"},{"id":"Workbooks/Filtering workbook data","title":"Filtering workbook data","description":"When you have a large dataset in a workbook, it can be challenging to identify specific trends, patterns, or insights. Filtering allows you to temporarily hide certain rows of data based on criteria you define for one or more columns. This leaves you with only the subset of data that meets your specific needs for analysis.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/filtering-workbook-data"},{"id":"Lakehouse/Pipelines/Last mile pipeline flow","title":"Last mile pipeline flow","description":"The Last Mile Pipeline transfers data from S3 storage to a database (DB), changing the storage type for easier access and use. Its primary function is to copy data from S3 into the designated DB.","permalink":"/datagol-knowlegde-base-v1/docs/Lakehouse/Pipelines/last-mile-pipeline"},{"id":"Workspaces/Managing roles and permissions of workspace","title":"Managing roles and permissions of workspace","description":"Users with sufficient permissions can modify the roles of existing workspace members.","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/managing-roles-and-permissions-of-workspace-users"},{"id":"Workspaces/Managing workspace access","title":"Managing workspace access","description":"You can specify workspace access settings when creating a new workspace. Refer to Creating a workspace.","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/manage-workspace-access"},{"id":"Workbooks/Refreshing cache","title":"Refreshing cache","description":"To access the most current data, you must initiate a cache refresh operation. Otherwise, the system will serve data from the existing cache. The timestamp of the last successful data synchronization is displayed in the upper right corner of the interface. This visual indicator provides you with immediate insight into the recency of the presented information.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/refreshing-Cache"},{"id":"Workspaces/Searching workspaces, workbooks, dashboards, widgets","title":"Searching workspaces, workbooks, dashboards, widgets","description":"A unified search experience in DataGOL allows you to seamlessly search across both your workbooks and dashboards from a single, intelligent search bar. This enhanced search is not just keyword matching, it intelligently analyzes the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/searching-workspace-workbooks-dashboard-widgets"},{"id":"Workbooks/Switching the storage provider","title":"Switching the storage provider","description":"Ensure your workbook has been published with the copy option. Typically, when a workbook is initially published via the copy option, it gets stored in the warehouse, and the default data provider is Spark.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/switching-the-storage-provider"},{"id":"Workbooks/Switching the storage type","title":"Switching the storage type","description":"1.  Open the published workbook. From the Settings menu, select Storage and Provider settings.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/switching-the-storage-type"},{"id":"Workbooks/Viewing and editing row details in a form","title":"Viewing and editing row details in a form","description":"Each row in a workbook can be expanded to view its full data in a form-like layout. All you need to do is select a row and click the expand or edit record icon. This supports contextual collaboration, allowing team members to discuss, clarify, or flag records directly within the workbook. You also have the option to keep this in View-Only mode, which prevents any other users from making edits.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/viewing-and-editing-row-details-in-a-form"},{"id":"Workbooks/Configure workbook settings/Viewing and editing the column catalog in workbook","title":"Viewing and editing the column catalog in workbook","description":"The Column Catalog maps each workbook column to its corresponding source column from connected data sources. Any metadata cataloged at the data source level is automatically surfaced at the workbook column. If a column is derived from multiple sources, descriptions from each level will be shown. Its primary purpose is to help users trace the raw source and inherit cataloging information.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/Configure workbook settings/viewing-editing-the-column-catalog-in-workbook"},{"id":"Workbooks/Viewing the column dependency graph","title":"Viewing the column dependency graph","description":"A column dependency graph visualizes how columns are connected through formulas\u2014showing chains where one formula-based column depends on another. It helps identify which columns are safe to delete and allows you to inspect dependencies for any specific column.","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/viewing-column-dependency-graph"},{"id":"Workbooks/Configure workbook settings/Viewing the workbook information","title":"Viewing the workbook information","description":"To view the workbook information, do the following:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/Configure workbook settings/viewing-the-workbook-information"},{"id":"Workbooks/Workbook columns","title":"Workbook columns","description":"Workbooks offer a rich set of column types designed to capture and manage your data effectively. By strategically choosing these column types, you can structure your data precisely to meet your specific requirements, ensuring accuracy, consistency, and enhanced functionality within your workbooks. The following column types are included in workbooks:","permalink":"/datagol-knowlegde-base-v1/docs/Workbooks/workbook-columns"},{"id":"Workspaces/Workspace users - roles and permissions","title":"Workspace users - roles and permissions","description":"Workspace users - Roles and permissions","permalink":"/datagol-knowlegde-base-v1/docs/Workspaces/workspace-user-roles-and-permissions"}],"unlisted":false}}')}}]);